head.script:
			var divisionId= WebSquare.net.getParameter( "divisionId" );
			var divisionNm = (typeof parent.getDivisionValue == "function")? parent.getDivisionValue(divisionId, "divisionNm"):"";
			var topMenuIndex = WebSquare.net.getParameter( "topMenuIndex" );

           /*******************initMnuStp******************************************************
             * function    : initMnuStp
             * Description : sub main 초기화
             * Parameter   : null
             * Return      : null
            **************************************************************************/
	        function initMnuStp() {
	            txtServiceNm.setLabel( divisionNm );
	            imgTop.setSrc( "/images/sub_title0"+topMenuIndex+".png" );
	            imgTop.setAlt( divisionNm + "컨텐츠 상단 이미지" );
	            if(typeof parent.getDivisionValue == "function") {
	            	txtMnuPath.setLabel( "HOME>" + parent.getDivisionValue(divisionId, "uMnuStp") );
	            	parent.closeTopMenu();
	            }
	        	init();
	        }

	        initMnuStp();
